export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  url: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
}

export interface Site {
  pages: Page[];
  tags: Map<string, Page[]>;
}

export interface BuildOptions {
  source: string;
  templates: string;
  output: string;
}

export interface ServeOptions extends BuildOptions {
  port: number;
}

import matter from "gray-matter";
import type { Frontmatter } from "./types.js";

export function parseFrontmatter(raw: string): {
  frontmatter: Frontmatter;
  content: string;
} {
  const { data, content } = matter(raw);
  const fm = data as Frontmatter;

  if (fm.tags !== undefined && !Array.isArray(fm.tags)) {
    fm.tags = [fm.tags as unknown as string];
  }

  if (fm.draft === undefined) {
    fm.draft = false;
  }

  return { frontmatter: fm, content: content.trim() };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return code;
    },
  }),
);

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

import Handlebars from "handlebars";
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join, extname } from "node:path";

export function createRenderer(templatesDir: string) {
  const partialsDir = join(templatesDir, "partials");

  if (existsSync(partialsDir)) {
    for (const file of readdirSync(partialsDir)) {
      if (extname(file) === ".hbs" || extname(file) === ".handlebars") {
        const name = file.replace(/\.(hbs|handlebars)$/, "");
        const source = readFileSync(join(partialsDir, file), "utf-8");
        Handlebars.registerPartial(name, source);
      }
    }
  }

  function readTemplate(name: string): string {
    for (const ext of [".hbs", ".handlebars"]) {
      const p = join(templatesDir, `${name}${ext}`);
      if (existsSync(p)) return readFileSync(p, "utf-8");
    }
    throw new Error(`Template not found: ${name}`);
  }

  const layoutSrc = readTemplate("layout");
  const layout = Handlebars.compile(layoutSrc);

  function render(templateName: string, data: Record<string, unknown>): string {
    const compiled = Handlebars.compile(readTemplate(templateName));
    const body = compiled(data);

    // If a `layout` key is explicitly passed, use it to distinguish
    // pages that use the layout from pages that skip it (like RSS).
    // Otherwise, wrap every render through the layout, passing body.
    return layout({ ...data, body });
  }

  return { render };
}

import type { Page } from "./types.js";

export function generateRss(pages: Page[], siteUrl: string): string {
  const items = pages
    .filter((p) => !p.frontmatter.draft)
    .sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    })
    .slice(0, 20)
    .map((p) => {
      const title = escapeXml(p.frontmatter.title);
      const url = escapeXml(`${siteUrl.replace(/\/$/, "")}${p.url}`);
      const date = p.frontmatter.date
        ? new Date(p.frontmatter.date).toUTCString()
        : "";
      return `    <item>
      <title>${title}</title>
      <link>${url}</link>
      <guid>${url}</guid>
      ${date ? `<pubDate>${escapeXml(date)}</pubDate>` : ""}
      <description>${escapeXml(p.html.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>Site Feed</title>
    <link>${escapeXml(siteUrl)}</link>
    <description>Latest posts</description>
${items}
  </channel>
</rss>`;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import { readdirSync, readFileSync, mkdirSync, writeFileSync, existsSync } from "node:fs";
import { join, relative, extname, dirname } from "node:path";
import type { Page, Site, BuildOptions } from "./types.js";
import { parseFrontmatter } from "./frontmatter.js";
import { markdownToHtml } from "./markdown.js";
import { createRenderer } from "./render.js";
import { generateRss } from "./rss.js";

export function build(options: BuildOptions): Site {
  const { source, templates, output } = options;
  const pages = collectPages(source);
  const tags = buildTagIndex(pages);
  const site: Site = { pages, tags };
  const renderer = createRenderer(templates);

  mkdirSync(output, { recursive: true });

  for (const page of pages) {
    if (page.frontmatter.draft) continue;
    const html = renderer.render("post", {
      title: page.frontmatter.title,
      date: page.frontmatter.date ?? "",
      tags: page.frontmatter.tags ?? [],
      content: page.html,
      url: page.url,
    });
    const outPath = join(output, page.path.replace(/\.md$/, ".html"));
    mkdirSync(dirname(outPath), { recursive: true });
    writeFileSync(outPath, html);
  }

  const published = pages.filter((p) => !p.frontmatter.draft);
  const sorted = [...published].sort((a, b) => {
    const da = a.frontmatter.date ?? "";
    const db = b.frontmatter.date ?? "";
    return db.localeCompare(da);
  });

  const indexHtml = renderer.render("index", {
    title: "Home",
    posts: sorted.map((p) => ({
      title: p.frontmatter.title,
      date: p.frontmatter.date ?? "",
      tags: p.frontmatter.tags ?? [],
      url: p.url,
    })),
  });
  writeFileSync(join(output, "index.html"), indexHtml);

  for (const [tag, tagPages] of tags.entries()) {
    const tagHtml = renderer.render("tag", {
      title: `Tag: ${tag}`,
      tag,
      posts: tagPages.map((p) => ({
        title: p.frontmatter.title,
        date: p.frontmatter.date ?? "",
        url: p.url,
      })),
    });
    const tagDir = join(output, "tags");
    mkdirSync(tagDir, { recursive: true });
    writeFileSync(join(tagDir, `${tag}.html`), tagHtml);
  }

  const rss = generateRss(published, "http://localhost:3000");
  writeFileSync(join(output, "feed.xml"), rss);

  copyAssets(source, output);

  return site;
}

function collectPages(source: string): Page[] {
  const pages: Page[] = [];
  walkDir(source, source, pages);
  return pages;
}

function walkDir(root: string, dir: string, pages: Page[]): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walkDir(root, full, pages);
    } else if (extname(entry.name) === ".md") {
      const raw = readFileSync(full, "utf-8");
      const { frontmatter, content } = parseFrontmatter(raw);
      const html = markdownToHtml(content);
      const rel = relative(root, full);
      const url = "/" + rel.replace(/\.md$/, ".html");
      pages.push({ path: rel, url, frontmatter, content, html });
    }
  }
}

function buildTagIndex(pages: Page[]): Map<string, Page[]> {
  const map = new Map<string, Page[]>();
  for (const page of pages) {
    if (page.frontmatter.draft) continue;
    for (const tag of page.frontmatter.tags ?? []) {
      const list = map.get(tag) ?? [];
      list.push(page);
      map.set(tag, list);
    }
  }
  return map;
}

function copyAssets(source: string, output: string): void {
  copyNonMd(source, source, output);
}

function copyNonMd(root: string, dir: string, out: string): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const src = join(dir, entry.name);
    const dst = join(out, relative(root, src));
    if (entry.isDirectory()) {
      mkdirSync(dst, { recursive: true });
      copyNonMd(root, src, out);
    } else if (extname(entry.name) !== ".md") {
      mkdirSync(dirname(dst), { recursive: true });
      writeFileSync(dst, readFileSync(src));
    }
  }
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { watch } from "chokidar";
import type { ServeOptions } from "./types.js";
import { build } from "./build.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__reload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
})();
</script>`;

export function serve(options: ServeOptions): void {
  const { source, templates, output, port } = options;

  const contentTypeMap: Record<string, string> = {
    ".html": "text/html",
    ".css": "text/css",
    ".js": "application/javascript",
    ".json": "application/json",
    ".xml": "application/xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".svg": "image/svg+xml",
    ".ico": "image/x-icon",
  };

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = req.url === "/" ? "/index.html" : req.url ?? "/index.html";
    const filePath = join(output, url);
    if (!existsSync(filePath) || statSync(filePath).isDirectory()) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }

    const ext = extname(filePath);
    const contentType = contentTypeMap[ext] ?? "application/octet-stream";

    let body = readFileSync(filePath, "utf-8");
    if (ext === ".html") {
      body = body.replace("</body>", `${RELOAD_SCRIPT}</body>`);
    }

    res.writeHead(200, { "Content-Type": contentType });
    res.end(body);
  });

  const wss = new WebSocketServer({ server });

  const clients = new Set<WebSocket>();
  wss.on("connection", (ws: WebSocket) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  function reload(): void {
    for (const ws of clients) ws.send("reload");
  }

  const watcher = watch([source, templates], {
    ignoreInitial: true,
  });

  watcher.on("change", () => {
    try {
      build({ source, templates, output });
      reload();
    } catch {
      // build failed — keep serving previous build
    }
  });

  server.listen(port, () => {
    console.log(`Dev server listening at http://localhost:${port}`);
  });
}

#!/usr/bin/env node
import { Command } from "commander";
import { join } from "node:path";
import { build } from "./build.js";
import { serve } from "./serve.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator")
  .option("-s, --source <dir>", "source directory of Markdown files", "content")
  .option("-t, --templates <dir>", "template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "output directory for generated HTML", "public")
  .option("--serve", "start a dev server with live reload")
  .option("-p, --port <number>", "dev server port", "3000")
  .action((opts) => {
    const source = join(process.cwd(), opts.source);
    const templates = join(process.cwd(), opts.templates);
    const output = join(process.cwd(), opts.output);
    const port = parseInt(opts.port, 10);

    if (opts.serve) {
      build({ source, templates, output });
      serve({ source, templates, output, port });
      return;
    }

    const site = build({ source, templates, output });
    const published = site.pages.filter((p) => !p.frontmatter.draft);
    console.log(`Built ${published.length} pages (${site.pages.length - published.length} drafts)`);
    console.log(`  Pages: ${published.length}`);
    console.log(`  Tags:  ${site.tags.size}`);
  });

program.parse();

