import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("extracts title, date, and tags", () => {
    const input = `---
title: My Post
date: 2025-06-01
tags:
  - js
  - web
---
Some content.`;

    const { frontmatter, content } = parseFrontmatter(input);
    expect(frontmatter.title).toBe("My Post");
    expect(frontmatter.date).toBe("2025-06-01");
    expect(frontmatter.tags).toEqual(["js", "web"]);
    expect(content).toBe("Some content.");
  });

  it("defaults draft to false when absent", () => {
    const input = `---
title: No Draft
---
Content`;

    const { frontmatter } = parseFrontmatter(input);
    expect(frontmatter.draft).toBe(false);
  });

  it("reads draft: true", () => {
    const input = `---
title: Secret
draft: true
---
Hidden`;

    const { frontmatter } = parseFrontmatter(input);
    expect(frontmatter.draft).toBe(true);
  });

  it("normalizes a string tag into an array", () => {
    const input = `---
title: OneTag
tags: solo
---
Body`;

    const { frontmatter } = parseFrontmatter(input);
    expect(frontmatter.tags).toEqual(["solo"]);
  });

  it("handles empty frontmatter", () => {
    const input = `No frontmatter here.`;
    const { frontmatter, content } = parseFrontmatter(input);
    expect(frontmatter.draft).toBe(false);
    expect(content).toBe("No frontmatter here.");
  });

  it("trims surrounding whitespace from content", () => {
    const input = `---
title: Trim
---

  padded content  

`;
    const { content } = parseFrontmatter(input);
    expect(content).toBe("padded content");
  });

  it("preserves arbitrary extra frontmatter keys", () => {
    const input = `---
title: Extra
author: Alice
custom: 42
---
.`;

    const { frontmatter } = parseFrontmatter(input);
    expect(frontmatter.author).toBe("Alice");
    expect(frontmatter.custom).toBe(42);
  });
});

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { existsSync, mkdtempSync, rmSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { createRenderer } from "../src/render.js";
import { build } from "../src/build.js";
import { generateRss } from "../src/rss.js";
import { markdownToHtml } from "../src/markdown.js";

const FIXTURES = join(import.meta.dirname ?? __dirname, "..", "test_fixtures");
const templatesDir = join(FIXTURES, "templates");
const sourceDir = join(FIXTURES, "source");

let outDir: string;

beforeAll(() => {
  outDir = mkdtempSync(join(FIXTURES, "..", "test-out-"));
});

afterAll(() => {
  if (existsSync(outDir)) rmSync(outDir, { recursive: true, force: true });
});

describe("createRenderer", () => {
  const renderer = createRenderer(templatesDir);

  it("renders a post template wrapped in layout", () => {
    const html = renderer.render("post", {
      title: "Test Post",
      date: "2025-01-01",
      tags: ["a", "b"],
      content: "<p>Hello</p>",
      url: "/test.html",
    });
    expect(html).toContain("<!DOCTYPE html>");
    expect(html).toContain("<title>Test Post</title>");
    expect(html).toContain('<meta name="generator" content="ssg">');
    expect(html).toContain("<p>Hello</p>");
    expect(html).toContain('<a href="/tags/a.html">a</a>');
  });

  it("renders the index template", () => {
    const html = renderer.render("index", {
      title: "Home",
      posts: [{ title: "A", url: "/a.html", date: "" }],
    });
    expect(html).toContain("Home");
    expect(html).toContain('<a href="/">Home</a>');
  });

  it("renders the tag template", () => {
    const html = renderer.render("tag", {
      title: "Tag: js",
      tag: "js",
      posts: [{ title: "Hello", url: "/hello.html", date: "2025-01-15" }],
    });
    expect(html).toContain("Tag: js");
    expect(html).toContain('<a href="/hello.html">Hello</a>');
  });

  it("throws for a non-existent template", () => {
    expect(() => renderer.render("missing", {})).toThrow("Template not found");
  });
});

describe("build", () => {
